#include <map>
#include <set>
#include <string>
#include <vector>
#include <fmt/ranges.h>

int main() {
  auto vc = std::vector<char>{'a', 'b', 'c'};
  auto vvc = std::vector<std::vector<char>>{vc, vc};
  if (fmt::format("{}", vc) != "['a', 'b', 'c']") return 1;
  if (fmt::format("{}", vvc) != "[['a', 'b', 'c'], ['a', 'b', 'c']]") return 2;
  if (fmt::format("{:n}", vvc) != "['a', 'b', 'c'], ['a', 'b', 'c']") return 3;
  if (fmt::format("{:n:n}", vvc) != "'a', 'b', 'c', 'a', 'b', 'c'") return 4;
  if (fmt::format("{:n:n:}", vvc) != "a, b, c, a, b, c") return 5;
  if (fmt::format("{}", std::map<std::string, int>{{"one", 1}, {"two", 2}}) !=
      "{\"one\": 1, \"two\": 2}") return 6;
  if (fmt::format("{:n}", std::map<std::string, int>{{"one", 1}}) !=
      "\"one\": 1") return 7;
  if (fmt::format("{}", std::set<std::string>{"one", "two"}) !=
      "{\"one\", \"two\"}") return 8;
  const char* arr[] = {"1234", "abcd"};
  if (fmt::format("{}", arr) != "[\"1234\", \"abcd\"]") return 9;
  if (fmt::format("{:n}", arr) != "\"1234\", \"abcd\"") return 10;
  if (fmt::format("{:n:}", arr) != "1234, abcd") return 11;
  if (fmt::format("{}", std::vector<std::string>{"\n\r\t\"\\"}) !=
      "[\"\\n\\r\\t\\\"\\\\\"]") return 12;
  if (fmt::format("{}", fmt::join(std::tuple<char, int, float>('a', 1, 2.0f), ", ")) != "a, 1, 2") return 13;
  fmt::print("all ok\n");
}

